declarations.code:
abbrev SignedFacetFiber (n : ℕ) (σ : RawSingularSimplex (Fin (n + 1) → ℝ) (n + 2))
    (i : Fin (n + 3)) (y : Fin (n + 1) → ℝ) :=
  {x : signedSimplexDomain (n + 1) // signedFacetFunction n σ i x.val = y}

